const PLACEHOLDER_CHINESE = "待补中文释义。";

function cleanText(value) {
  return String(value || "").trim();
}

function hasContent(value) {
  const text = cleanText(value);
  return text && text !== PLACEHOLDER_CHINESE;
}

function duplicateKey(word) {
  return `${cleanText(word.swedish).toLowerCase()}@@${cleanText(word.pos).toLowerCase()}`;
}

function completenessScore(word) {
  let score = 0;
  if (hasContent(word.chinese)) score += 80;
  if (hasContent(word.example)) score += 24;
  if (hasContent(word.collocations)) score += 18;
  if (hasContent(word.related_words || word.relatedWords)) score += 18;
  if (hasContent(word.forms)) score += 12;
  if (hasContent(word.english)) score += 8;
  if (hasContent(word.pos_detail || word.posDetail)) score += 3;
  if (cleanText(word.chinese) === PLACEHOLDER_CHINESE) score -= 100;
  return score;
}

function normalizeTags(value) {
  const rawTags = Array.isArray(value) ? value : cleanText(value).split(",");
  return rawTags.map((item) => cleanText(item)).filter(Boolean);
}

function normalizeEnrichedWord(word) {
  word.pos_detail = cleanText(word.pos_detail || word.posDetail);
  word.related_words = cleanText(word.related_words || word.relatedWords);
  word.tags = normalizeTags(word.tags).length ? normalizeTags(word.tags) : normalizeTags(word.tag);
  delete word.posDetail;
  delete word.relatedWords;
  delete word.tag;
  return word;
}

function removeDuplicateWords(packs) {
  const selectedByKey = new Map();

  for (const pack of packs) {
    for (const word of pack.words) {
      const key = duplicateKey(word);
      if (!cleanText(word.swedish)) {
        continue;
      }
      if (!selectedByKey.has(key)) {
        selectedByKey.set(key, word);
      } else if (completenessScore(word) > completenessScore(selectedByKey.get(key))) {
        selectedByKey.set(key, word);
      }
    }
  }

  const emitted = new Set();
  let removed = 0;

  for (const pack of packs) {
    const dedupedWords = [];
    for (const word of pack.words) {
      const key = duplicateKey(word);
      if (!cleanText(word.swedish)) {
        dedupedWords.push(word);
        continue;
      }
      if (emitted.has(key)) {
        removed += 1;
        continue;
      }
      emitted.add(key);
      dedupedWords.push(selectedByKey.get(key) || word);
    }
    pack.words = dedupedWords;
  }

  return removed;
}

let changed = 0;

for (const pack of documentWordPacks) {
  for (const word of pack.words) {
    const update = enrichments.get(`${word.swedish}@@${word.pos}`) || enrichments.get(word.swedish);
    if (!update) continue;
    Object.assign(word, update);
    if (word.swedish === "vara" && normalizeTags(word.tags || word.tag).includes("Rivstart A1/A2 Kapitel 4")) {
      Object.assign(word, enrichments.get("vara@@noun"));
    }
    normalizeEnrichedWord(word);
    changed += 1;
  }
}

for (const pack of documentWordPacks) {
  pack.words.forEach(normalizeEnrichedWord);
}

const removedDuplicates = removeDuplicateWords(documentWordPacks);
const output = `export const documentWordPacks = ${JSON.stringify(documentWordPacks, null, 2)};\n`;
writeFileSync(new URL("../document-vocab-data.js", import.meta.url), output);
console.log(`Updated ${changed} document vocabulary entries.`);
console.log(`Removed ${removedDuplicates} duplicate document vocabulary entries.`);
